package main

import "fmt"

type Rect struct{ W, H int }

func (r Rect) Area() int {
	return r.W * r.H
}

func (r Rect) Perimeter() int {
	return 2 * (r.W + r.H)
}

// Scaled changes its own copy of r and returns it
func (r Rect) Scaled(k int) Rect {
	r.W *= k
	r.H *= k
	return r
}

func main() {
	r := Rect{W: 3, H: 4}
	fmt.Printf("Area: %d\n", r.Area())
	fmt.Printf("Perimeter: %d\n", r.Perimeter())
	big := r.Scaled(2)
	fmt.Printf("Scaled area: %d\n", big.Area())
	fmt.Printf("Original: %+v\n", r)
}

