type Counter struct{ Count int }

func (c *Counter) Inc() {
	c.Count++
}

func (c *Counter) Add(n int) {
	c.Count += n
}

// IncCopy is the bug: c is a copy, so the change is lost
func (c Counter) IncCopy() {
	c.Count++
}

func main() {
	var c Counter
	c.Inc()
	fmt.Printf("Inc: %d\n", c.Count)
	c.Inc()
	fmt.Printf("Inc: %d\n", c.Count)
	c.IncCopy()
	fmt.Printf("IncCopy: %d\n", c.Count)
	c.IncCopy()
	fmt.Printf("IncCopy: %d\n", c.Count)
	c.Add(5)
	fmt.Printf("Add 5: %d\n", c.Count)
}

