package main

import "fmt"

type Account struct{ Balance int }

func (a *Account) Deposit(amount int) {
	a.Balance += amount
}

func (a *Account) Withdraw(amount int) bool {
	if amount > a.Balance {
		return false
	}
	a.Balance -= amount
	return true
}

func main() {
	var a Account
	a.Deposit(50)
	fmt.Printf("Deposit 50: %d\n", a.Balance)
	ok := a.Withdraw(20)
	fmt.Printf("Withdraw 20: %t, %d\n", ok, a.Balance)
	ok = a.Withdraw(100)
	fmt.Printf("Withdraw 100: %t, %d\n", ok, a.Balance)
	a.Deposit(15)
	fmt.Printf("Deposit 15: %d\n", a.Balance)
}

steps.body:
Go has no constructors. By convention a function named `NewT` builds a ready-to-use `T` from its arguments and returns a pointer to it:

```go
func NewStack(name string) *Stack {
	return &Stack{name: name}
}
```

`&Stack{name: name}` creates the struct and takes its address in one step. Returning that address is safe: escape analysis keeps the struct alive, on the heap when it outlives the function. Returning a pointer means every method works on one shared stack. A copied `Stack` value would copy only the slice header, so two copies would share a backing array but keep separate lengths.

**Exported names** start with a capital letter (`Push`, `Len`) and are visible to other packages. Lowercase names (`name`, `items`) are unexported, private to their package. That is how a type hides its data and offers methods instead. Visibility is per package, not per type, so in a one-file program `main` could still reach `s.items`. Other packages could not.

A getter for an unexported field is named after the field, without `Get`: `Name()` returns `name`.

Inside a method, `s.items` works even though `s` is a `*Stack`. Go dereferences the pointer for you, so you never write `(*s).items`.

example.code:
package main

import "fmt"

type Stack struct {
	name  string
	items []int
}

func NewStack(name string) *Stack {
	return &Stack{name: name}
}

func (s *Stack) Name() string {
	return s.name
}

func (s *Stack) Push(v int) {
	s.items = append(s.items, v)
}

func (s *Stack) Pop() (int, bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	last := len(s.items) - 1
	v := s.items[last]
	s.items = s.items[:last]
	return v, true
}

func (s *Stack) Len() int {
	return len(s.items)
}

func main() {
	s := NewStack("trays")
	s.Push(10)
	s.Push(20)
	s.Push(30)
	fmt.Printf("%s: %d items\n", s.Name(), s.Len())
	for s.Len() > 0 {
		v, _ := s.Pop()
		fmt.Printf("Popped: %d\n", v)
	}
	_, ok := s.Pop()
	fmt.Printf("Pop on empty: %t\n", ok)
}

