package main

import "fmt"

type Queue struct {
	name  string
	items []string
}

func NewQueue(name string) *Queue {
	return &Queue{name: name}
}

func (q *Queue) Name() string {
	return q.name
}

func (q *Queue) Enqueue(name string) {
	q.items = append(q.items, name)
}

func (q *Queue) Dequeue() (string, bool) {
	if len(q.items) == 0 {
		return "", false
	}
	first := q.items[0]
	q.items = q.items[1:]
	return first, true
}

func (q *Queue) Len() int {
	return len(q.items)
}

func main() {
	q := NewQueue("bakery")
	q.Enqueue("Ana")
	q.Enqueue("Ben")
	q.Enqueue("Cy")
	fmt.Printf("%s: %d waiting\n", q.Name(), q.Len())
	for q.Len() > 0 {
		name, _ := q.Dequeue()
		fmt.Printf("Serving: %s\n", name)
	}
	_, ok := q.Dequeue()
	fmt.Printf("Dequeue on empty: %t\n", ok)
}

