package main

import "fmt"

type Celsius float64
type Fahrenheit float64
type Scores []int

func (c Celsius) ToFahrenheit() Fahrenheit {
	return Fahrenheit(c*9/5 + 32)
}

func (s Scores) Average() float64 {
	if len(s) == 0 {
		return 0
	}
	var total int
	for _, v := range s {
		total += v
	}
	return float64(total) / float64(len(s))
}

// Curve changes the shared elements, so the caller sees it
func (s Scores) Curve(n int) {
	for i := range s {
		s[i] += n
	}
}

func main() {
	degrees := 21.5
	temp := Celsius(degrees)
	fmt.Printf("%.1f C = %.1f F\n", temp, temp.ToFahrenheit())
	raw := []int{80, 92, 75}
	s := Scores(raw)
	fmt.Printf("Average: %.1f\n", s.Average())
	s.Curve(5)
	fmt.Println("Curved:", raw)
	fmt.Printf("Average: %.1f\n", s.Average())
}

