package main

import "fmt"

const FeetPerMeter = 3.28084

type Meters float64
type Feet float64
type Prices []float64

func (m Meters) ToFeet() Feet {
	return Feet(m * FeetPerMeter)
}

func (p Prices) Total() float64 {
	var total float64
	for _, v := range p {
		total += v
	}
	return total
}

func (p Prices) Raise(amount float64) {
	for i := range p {
		p[i] += amount
	}
}

func main() {
	length := 2.5
	raw := []float64{4.99, 12.5, 3.25}
	m := Meters(length)
	fmt.Printf("%.2f m = %.2f ft\n", m, m.ToFeet())
	p := Prices(raw)
	fmt.Printf("Total: %.2f\n", p.Total())
	p.Raise(1)
	fmt.Printf("Total after raise: %.2f\n", p.Total())
}
